tool("create_booking","Hold seats and create a booking in HELD status for 20 minutes. Requires explicit customer confirmation of itinerary, passengers and total.",{"flight_ids":dict(type="array",items={"type":"string"},description="Flight ids from search_flights, one per segment"),"fare_family":str_("Fare family",enum=["BASIC","STANDARD","FLEX","BUSINESS"]),"passengers":dict(type="array",items={"type":"object","properties":{"first_name":{"type":"string"},"last_name":{"type":"string"},"type":{"type":"string","enum":["adult","child","infant"]},"date_of_birth":{"type":"string"},"companion_id":{"type":"string"}},"required":["first_name","last_name","type"]}),"allow_duplicate":dict(type="boolean",description="Only after the customer confirms they really want a second booking for the same passengers on the same flight"),"unaccompanied_minor":dict(type="boolean",description="True when a child 5-17 travels without an adult on the booking; adds the Unaccompanied Minor service and fee"),"contact_customer_id":str_("Account to attach the booking to, if verified or logged in"),"contact_phone":str_("Phone for guest bookings"),"contact_email":str_("Email for guest bookings")},["flight_ids","fare_family","passengers"],"action"),
