tool("add_baggage","Add a prepaid baggage pack. Requires confirmation of price.",{"pnr":pnr,"segment_id":seg,"passenger_id":str_("Passenger id"),"kg":int_("Pack size",enum=[5,10,15]),"payment_method":str_("Payment",enum=["saved_method","skywallet","payment_link"]),"payment_method_id":str_("Saved method id")},["pnr","segment_id","passenger_id","kg","payment_method"],"action"),
