tool("add_special_assistance","Add a free assistance request.",{"pnr":pnr,"passenger_id":str_("Passenger id"),"type":str_("Service",enum=["wheelchair_ramp","wheelchair_steps","wheelchair_cabin","visual","hearing","elderly_escort"]),"notes":str_("Short practical note, no diagnoses")},["pnr","passenger_id","type"],"action"),
